// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useRef, useMemo, useEffect } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';
// [Start Google Fonts Loader]
const useFontLoader = (fonts: string[]) => {
  const stableFonts = useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
// [End Google Fonts Loader]



export type GlowingOrbGridProps = Record<string, any>;

const GlowingOrbGrid: React.FC<GlowingOrbGridProps> = ({
  backgroundColor = "#05000a",
  transparentBackground = true,
  durationInSeconds = 6,
  orbColor = "#a855f7",
  gridColor = "#2e1065",
  highlightColor = "#c084fc",
  textColor = "#ffffff",
  titleText = "The Power of Motion Design",
  // Updated defaults for a denser, larger grid
  rows = 20,
  cols = 24,
  tileSize = 60,
}) => {
  useFontLoader(["Orbitron"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const durationInFrames = durationInSeconds * fps;

  const bgColor = transparentBackground ? backgroundColor : backgroundColor;

  // -- Motion Logic --

  // Orb moves from Right to Left
  const orbProgress = interpolate(frame, [0, durationInFrames], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });
  
  // Calculate grid dimensions
  const gridWidth = cols * tileSize;
  const gridHeight = rows * tileSize;
  
  // Orb Position in Grid Space (X axis)
  // Adjusted offset to ensure it enters and leaves the wider grid cleanly
  const startX = gridWidth * 1.1; 
  const endX = -gridWidth * 0.1;
  const orbX = interpolate(orbProgress, [0, 1], [startX, endX]);
  
  // -- Text Reveal Logic --
  const textReveal = interpolate(frame, [fps * 0.5, durationInFrames * 0.8], [0, 100], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Orbitron",
        overflow: "hidden",
        // Reduced perspective value to exaggerate depth (front tiles larger, back smaller)
        perspective: "600px", 
      }}
    >
      {/* Background Gradient */}
      <AbsoluteFill
        style={{
          background: `radial-gradient(circle at 50% 30%, ${gridColor} 0%, ${bgColor} 80%)`,
          opacity: 0.5,
          zIndex: 0,
        }}
      />

      {/* 3D Grid Container */}
      <div
        style={{
          position: "absolute",
          width: gridWidth,
          height: gridHeight,
          left: (width - gridWidth) / 2,
          // Moved up significantly to be a foreground element
          top: height * 0.3, 
          transformStyle: "preserve-3d",
          // Increased rotation slightly for better floor perspective
          transform: `rotateX(65deg) translateZ(-50px)`,
          display: "flex",
          flexWrap: "wrap",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        {/* Tiles */}
        {Array.from({ length: rows * cols }).map((_, i) => {
          const row = Math.floor(i / cols);
          const col = i % cols;
          
          // Tile's center X coordinate relative to grid
          const tileCenterX = col * tileSize + tileSize / 2;
          
          // Distance from orb
          const dist = Math.abs(orbX - tileCenterX);
          
          // Vertical check 
          const rowDist = Math.abs(row - rows / 2 + 0.5);
          
          // Distance effect calculation
          // Increased the Y-influence slightly to make the wake wider vertically
          const distanceEffect = Math.sqrt(dist * dist + (rowDist * tileSize * 1.8) ** 2);

          // Calculate Lift
          // Increased range from [0, 400] to [0, 600] to widen the "hill"
          const lift = interpolate(distanceEffect, [0, 600], [80, 0], {
            extrapolateRight: "clamp",
            extrapolateLeft: "clamp",
          });
          
          const organicLift = lift > 0 ? lift : 0;
          
          // Highlight intensity
          // Increased range and max opacity for more vivid bounce light
          const opacity = interpolate(distanceEffect, [0, 500], [1, 0], {
            extrapolateRight: "clamp",
          });

          // Scale effect
          const scale = interpolate(distanceEffect, [0, 400], [1.15, 1], {
             extrapolateRight: "clamp",
          });

          return (
            <div
              key={i}
              style={{
                width: tileSize - 2, // Smaller gap for denser look
                height: tileSize - 2,
                margin: 1,
                backgroundColor: `rgba(20, 20, 30, 0.4)`,
                border: `1px solid ${gridColor}`,
                transform: `translateZ(${organicLift}px) scale(${scale})`,
                // Increased shadow intensity for vivid glow
                boxShadow: `0 0 ${organicLift}px ${gridColor}`,
                transition: "none",
                position: "relative",
              }}
            >
               {/* Inner glow for active tiles */}
               <div style={{
                  position: "absolute",
                  inset: 0,
                  backgroundColor: highlightColor,
                  // More vivid opacity application
                  opacity: opacity * 0.8, 
               }} />
            </div>
          );
        })}

        {/* The Orb (Inside the 3D space) */}
        <div
          style={{
            position: "absolute",
            left: orbX - 30, 
            top: (gridHeight / 2) - 30,
            width: 60,
            height: 60,
            // Lifted higher to match new wave height
            transform: `translateZ(100px) rotateX(-65deg)`, 
            borderRadius: "50%",
            background: `radial-gradient(circle at 30% 30%, #fff, ${orbColor})`,
            // Stronger, wider glow
            boxShadow: `0 0 60px 20px ${orbColor}, 0 0 100px 40px ${highlightColor}`,
            zIndex: 999,
          }}
        />
      </div>

      {/* Text Overlay (Screen Space) */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          zIndex: 10,
          pointerEvents: "none",
          marginTop: -height * 0.1, // Offset text up slightly to clear the taller grid
        }}
      >
        <div style={{ position: "relative", overflow: "hidden" }}>
          <h1
            style={{
              color: textColor,
              fontSize: 80,
              fontWeight: 700,
              margin: 0,
              letterSpacing: "4px",
              textTransform: "uppercase",
              textShadow: `0 0 20px ${gridColor}`,
              clipPath: `inset(0 ${100 - textReveal}% 0 0)`,
            }}
          >
            {titleText}
          </h1>
          {/* Scanline/Glow on the leading edge of text */}
          <div 
             style={{
                position: "absolute",
                top: 0,
                bottom: 0,
                left: `${textReveal}%`,
                width: 4,
                background: highlightColor,
                boxShadow: `0 0 20px 5px ${highlightColor}`,
                opacity: textReveal > 0 && textReveal < 100 ? 1 : 0,
             }}
          />
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default GlowingOrbGrid;